490		/**
491		 * Add job.
492		 *
493		 * @param WP_REST_Request $request The request object.
494		 *
495		 * @return WP_REST_Response
496		 */
497		public function add_job( WP_REST_Request $request ): WP_REST_Response {
498			$params = $request->get_params();
499	
500			$default_values = $this->option_adapter->defaults_job();
501	
502			$type   = $params['type'];
503			$job_id = $this->option_adapter->next_job_id();
504	
505			$job = [
506				'activ' => true,
507				'jobid' => $job_id,
508			];
509	
510			switch ( $type ) {
511				case 'files':
512					$job['type'] = $this->job_types_adapter->get_type_job_file();
513					$job['name'] = $this->job_types_adapter->get_name_job_files();
514					break;
515				case 'database':
516					$job['type'] = $this->job_types_adapter->get_type_job_database();
517					$job['name'] = $this->job_types_adapter->get_name_job_database();
518					break;
519				case 'mixed':
520					$job['type'] = $this->job_types_adapter->get_type_job_both();
521					$job['name'] = $this->job_types_adapter->get_name_job_both();
522					break;
523			}
524	
525			$job = wp_parse_args( $job, $default_values );
526	
527			foreach ( $job as $key => $value ) {
528				$this->option_adapter->update( $job_id, $key, $value );
529			}
530	
531			$cron_next = $this->cron_adapter->cron_next( $job['cron'] );
532	
533			wp_clear_scheduled_hook( 'backwpup_cron', [ 'arg' => (int) $job_id ] );
534			wp_schedule_single_event( $cron_next, 'backwpup_cron', [ 'arg' => (int) $job_id ] );
535	
536			/**
537			 * Fires after a new job is added.
538			 *
539			 * @param array $job The job data.
540			 */
541			do_action( 'backwpup_add_job', $job );
542	
543			return rest_ensure_response(
544				[
545					'success' => true,
546					'message' => __( 'You scheduled a new backup successfully!<br>Now you can configure it as you wish.', 'backwpup' ),
547				]
548				);
549		}
