586		/**
587		 * Save the job frequency settings via the REST API.
588		 *
589		 * This function updates the cron schedule for a given job and reschedules it accordingly.
590		 * It generates a new cron expression based on user input and stores it in the database.
591		 *
592		 * @param WP_REST_Request $request The REST API request containing job settings.
593		 *
594		 * @return WP_REST_Response|WP_Error|WP_HTTP_Response The response containing the updated job schedule or an error message.
595		 */
596		public function save_job_settings( WP_REST_Request $request ) {
597			$params = $request->get_params(); // Get request parameters.
598			$return = [];
599	
600			try {
601				// Extract parameters from the request.
602				$job_id    = $params['job_id'];
603				$frequency = $params['frequency'];
604	
605				// Set default values if parameters are not provided.
606				$params['start_time']        = isset( $params['start_time'] ) ? $params['start_time'] : '00:00';
607				$params['hourly_start_time'] = isset( $params['hourly_start_time'] ) ? (int) $params['hourly_start_time'] : 0;
608				$day_of_week                 = (int) isset( $params['day_of_week'] ) ? $params['day_of_week'] : 0;
609				$day_of_month                = isset( $params['day_of_month'] ) ? $params['day_of_month'] : '';
610	
611				// Convert start_time into hour and minute parts.
612				$start_time = explode( ':', $params['start_time'] );
613	
614				// Adjust start time for hourly jobs.
615				if ( 'hourly' === $frequency ) {
616					$start_time = [ '*', $params['hourly_start_time'] ];
617				}
618	
619				// Update frequency.
620				$this->option_adapter->update( $job_id, 'frequency', $frequency );
621	
622				if ( 'link' === $frequency ) {
623					$next_backup = __( 'External link', 'backwpup' );
624					// Update active type.
625					$this->option_adapter->update( $job_id, 'activetype', $frequency );
626					wp_clear_scheduled_hook( 'backwpup_cron', [ 'arg' => (int) $job_id ] );
627	
628				} else {
629					// Generate new cron expression based on the selected frequency and time settings.
630					$new_cron_expression = $this->cron_adapter->get_basic_cron_expression(
631						$frequency,
632						$start_time[0],
633						$start_time[1],
634						$day_of_week,
635						$day_of_month
636					);
637	
638					// Update the cron expression in the job settings.
639					$this->option_adapter->update( $job_id, 'cron', $new_cron_expression );
640	
641					// Re-schedule the job with the updated cron schedule.
642					$this->job_adapter->schedule_job( $job_id );
643	
644					// Get the next scheduled execution time.
645					$cron_next = $this->cron_adapter->cron_next( $new_cron_expression );
646	
647					// Update activetype.
648					$this->option_adapter->update( $job_id, 'activetype', 'wpcron' );
649	
650					// Prepare response with next backup schedule.
651					$next_backup = sprintf(
652					// translators: %1$s = date, %2$s = time.
653						__( '%1$s at %2$s', 'backwpup' ),
654						wp_date( get_option( 'date_format' ), $cron_next ),
655						wp_date( get_option( 'time_format' ), $cron_next )
656					);
657				}
658	
659				$return['next_backup'] = $next_backup;
660				$return['status']      = 200;
661				$return['message']     = __('Job settings saved successfully.', 'backwpup'); // @phpcs:ignore
662	
663			} catch ( Exception $e ) {
664				// Handle errors.
665				$return['status'] = 500;
666				$return['error']  = $e->getMessage();
667			}
668	
669			// Return response as a valid WP REST API response.
670			return rest_ensure_response( $return );
671		}
